import{H as e,ht as t,nt as n,tt as r}from"./chunks/framework.t9tCn7sc.js";var i=JSON.parse(`{"title":"Command Line Interface","description":"","frontmatter":{},"headers":[],"relativePath":"introduction/cli.md","filePath":"introduction/cli.md","lastUpdated":1793470662000}`),a={name:`introduction/cli.md`};function o(e,i,a,o,s,c){return t(),r(`div`,null,[...i[0]||=[n(`<h1 id="command-line-interface" tabindex="-1">Command Line Interface <a class="header-anchor" href="#command-line-interface" aria-label="Permalink to “Command Line Interface”">​</a></h1><p>Running <code>turna</code> without a subcommand loads configuration and starts configured loads, preprocessors, servers, and services. If no configuration is found, Turna starts with the defaults and has nothing to run.</p><h2 id="root-command" tabindex="-1">Root Command <a class="header-anchor" href="#root-command" aria-label="Permalink to “Root Command”">​</a></h2><div class="language-sh"><button title="Copy code" data-copied="Copied" class="copy"></button><span class="lang">sh</span><pre class="shiki shiki-themes vesper vesper" style="--shiki-light:#FFF;--shiki-dark:#FFF;--shiki-light-bg:#101010;--shiki-dark-bg:#101010;" tabindex="0" dir="ltr"><code><span class="line"><span style="--shiki-light:#FFC799;--shiki-dark:#FFC799;">turna</span><span style="--shiki-light:#FFF;--shiki-dark:#FFF;"> [flags]</span></span></code></pre></div><p>Flags:</p><table tabindex="0"><thead><tr><th>Flag</th><th>Default</th><th>Description</th></tr></thead><tbody><tr><td><code>-l</code>, <code>--log-level</code></td><td><code>info</code></td><td>Log level. Command-line value overrides loaded config.</td></tr><tr><td><code>-v</code>, <code>--version</code></td><td></td><td>Print version metadata.</td></tr></tbody></table><p>Config sources are selected with environment variables, not flags. See <a href="./../reference/config.html#application-config-sources">Application Config Sources</a>.</p><h2 id="api-command" tabindex="-1">API Command <a class="header-anchor" href="#api-command" aria-label="Permalink to “API Command”">​</a></h2><div class="language-sh"><button title="Copy code" data-copied="Copied" class="copy"></button><span class="lang">sh</span><pre class="shiki shiki-themes vesper vesper" style="--shiki-light:#FFF;--shiki-dark:#FFF;--shiki-light-bg:#101010;--shiki-dark-bg:#101010;" tabindex="0" dir="ltr"><code><span class="line"><span style="--shiki-light:#FFC799;--shiki-dark:#FFC799;">turna</span><span style="--shiki-light:#99FFE4;--shiki-dark:#99FFE4;"> api</span><span style="--shiki-light:#99FFE4;--shiki-dark:#99FFE4;"> --url</span><span style="--shiki-light:#99FFE4;--shiki-dark:#99FFE4;"> http://localhost:8080/health</span><span style="--shiki-light:#99FFE4;--shiki-dark:#99FFE4;"> --method</span><span style="--shiki-light:#99FFE4;--shiki-dark:#99FFE4;"> GET</span></span></code></pre></div><p>The <code>api</code> command is a small HTTP caller. It exits with an error when a response status is outside the <code>2xx</code> range.</p><p>Flags:</p><table tabindex="0"><thead><tr><th>Flag</th><th>Default</th><th>Description</th></tr></thead><tbody><tr><td><code>-u</code>, <code>--url</code></td><td></td><td>URL to call. Can be provided more than once.</td></tr><tr><td><code>-m</code>, <code>--method</code></td><td><code>GET</code></td><td>HTTP method.</td></tr><tr><td><code>-k</code>, <code>--insecure</code></td><td><code>false</code></td><td>Skip TLS certificate verification.</td></tr><tr><td><code>-s</code>, <code>--silent</code></td><td><code>false</code></td><td>Suppress response body output.</td></tr></tbody></table><h2 id="whoami-command" tabindex="-1">Whoami Command <a class="header-anchor" href="#whoami-command" aria-label="Permalink to “Whoami Command”">​</a></h2><div class="language-sh"><button title="Copy code" data-copied="Copied" class="copy"></button><span class="lang">sh</span><pre class="shiki shiki-themes vesper vesper" style="--shiki-light:#FFF;--shiki-dark:#FFF;--shiki-light-bg:#101010;--shiki-dark-bg:#101010;" tabindex="0" dir="ltr"><code><span class="line"><span style="--shiki-light:#FFC799;--shiki-dark:#FFC799;">turna</span><span style="--shiki-light:#99FFE4;--shiki-dark:#99FFE4;"> whoami</span><span style="--shiki-light:#99FFE4;--shiki-dark:#99FFE4;"> --address</span><span style="--shiki-light:#99FFE4;--shiki-dark:#99FFE4;"> :8080</span><span style="--shiki-light:#99FFE4;--shiki-dark:#99FFE4;"> --name</span><span style="--shiki-light:#99FFE4;--shiki-dark:#99FFE4;"> app</span></span></code></pre></div><p>The <code>whoami</code> command runs a server that answers with host and request details, like <code>traefik/whoami</code>. It does not load configuration. Endpoints are described in the <a href="./../reference/server/http/middlewares/whoami.html#endpoints"><code>whoami</code> middleware</a>.</p><p>Flags:</p><table tabindex="0"><thead><tr><th>Flag</th><th>Default</th><th>Description</th></tr></thead><tbody><tr><td><code>-a</code>, <code>--address</code></td><td><code>:80</code></td><td>Listen address.</td></tr><tr><td><code>-n</code>, <code>--name</code></td><td></td><td>Name printed in responses.</td></tr><tr><td><code>--env</code></td><td><code>false</code></td><td>Allow printing the environment with <code>?env=true</code>.</td></tr><tr><td><code>--cert</code></td><td></td><td>TLS certificate file. Requires <code>--key</code>.</td></tr><tr><td><code>--key</code></td><td></td><td>TLS key file. Requires <code>--cert</code>.</td></tr><tr><td><code>--max-wait</code></td><td><code>30s</code></td><td>Upper bound for <code>?wait</code>.</td></tr></tbody></table><h2 id="shell-completion" tabindex="-1">Shell Completion <a class="header-anchor" href="#shell-completion" aria-label="Permalink to “Shell Completion”">​</a></h2><p>Cobra provides completion subcommands through <code>turna completion</code>. Run <code>turna completion --help</code> for the supported shells.</p>`,19)]])}var s=e(a,[[`render`,o]]);export{i as __pageData,s as default};